    ($SATQ$ebb717ab$SATQ$, $SATQ$c9d1415e-a7ee-4cc6-826b-fc650c58fc3b$SATQ$::uuid, $SATQ$0b9224cf-a987-484e-8376-df9d01b47ef7$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.B.$SATQ$, $SATQ$Nonlinear equations in one variable and systems of equations in two variables $SATQ$, $SATQ$H$SATQ$, 7, $SATQ$spr$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="x squared minus 34 x plus c equals 0"><mrow>
	<mrow>
